insert into "industries" ("industry_id", "industry_code", "industry_name", "description", "defining_characteristics", "top_pain_point_weights", "key_metrics", "red_flags", "empathy_language", "recommended_benchmarks", "created_at", "updated_at", "industry_subtitle", "why_industry_context_matters", "top_pain_points", "diagnostic_adjustments", "red_flags_description", "stage_thresholds_inr") values ('1', 'saas', 'Technology & SaaS', 'Software products, AI platforms, B2B and B2C apps, developer tools, and marketplace platforms. Revenue is product-delivered, not people-delivered. Scaling is achieved through deployment not headcount. The core economics are built around recurring revenue, unit economics, and retention — not project delivery or physical goods.', '["India is the world''s third-largest startup ecosystem with 100+ SaaS unicorns, but 90% of Indian SaaS companies still struggle with global GTM — selling to India versus exporting globally requires completely different strategies", "Unit economics are uniquely pressured — Indian market price sensitivity forces LTVs far lower than US benchmarks; CAC to LTV ratios that are healthy in the US are dangerous in India-first markets", "Talent is abundant but specialised sales talent — especially enterprise SaaS account executives — is critically scarce outside Bangalore and Hyderabad", "Regulatory complexity is lower than other verticals but data localisation requirements under DPDP Act 2023 are emerging as a significant operational risk"]', '{"FND-006": 1.05, "GTM-002": 1.3, "GTM-007": 1.05, "IVA-001": 1.5, "PRD-001": 1.15, "SAL-001": 1.05, "SAL-003": 1.3, "SAL-005": 1.5}', '["MRR (Monthly Recurring Revenue)", "ARR (Annual Recurring Revenue)", "NRR (Net Revenue Retention)", "Gross Margin", "CAC (Customer Acquisition Cost)", "LTV (Lifetime Value)", "LTV:CAC Ratio", "Churn Rate (monthly)", "Payback Period", "Magic Number"]', '{"expansion_revenue": "none is a red flag", "ltv_cac_ratio_below": 3, "churn_monthly_pct_above": 3, "payback_period_months_above": 18, "b2b_saas_pricing_below_INR_per_month": 999}', '{"use": ["customers", "users", "retention", "activation", "NRR", "cohort", "pipeline", "ARR", "product"], "avoid": [{"say": "customers", "instead_of": "clients"}, {"say": "product", "instead_of": "project"}], "psychological_framing": "Acknowledge the pressure of post-funding valuation expectations. SaaS founders feel uniquely exposed to investor scrutiny on unit economics. Frame metric discussions as clarity tools not judgment."}', '{"nrr_min_pct": 110, "ltv_cac_ratio_min": 3, "arr_growth_yoy_max_x": 3, "arr_growth_yoy_min_x": 2, "gross_margin_min_pct": 70, "monthly_churn_max_pct": 2, "benchmarks_description": "Good Indian SaaS: NRR 110%+, Gross Margin 70%+, LTV:CAC 3:1+, Monthly Churn below 2%, ARR growth 2-3x year-on-year at early stages"}', '2026-07-10 11:24:52.14702+00', '2026-07-11 04:28:09.765561+00', 'Software products, AI platforms, B2B/B2C apps, developer tools, marketplace platforms', 'A weak sales pipeline for a SaaS founder is a CRM and outbound discipline problem. Without industry context, the diagnostic engine produces the right diagnosis for the wrong context — and the recommended intervention will not fit the founder''s actual reality.', '[{"weight": "CRITICAL", "pain_point_name": "No Product-Market Fit", "indian_specific_nuance": "Indian B2B SaaS founders often mistake enterprise POC agreements for PMF — large Indian companies pilot everything and buy nothing", "why_high_risk_in_this_vertical": "SaaS products are expensive to build and easy to over-engineer; PMF is elusive because early users are often enthusiasts not buyers"}, {"weight": "CRITICAL", "pain_point_name": "High Customer Churn", "indian_specific_nuance": "Indian SMB customers have extremely low switching costs and high price sensitivity; contract discipline is weak", "why_high_risk_in_this_vertical": "SaaS unit economics are destroyed by churn; a 5% monthly churn makes sustainable growth mathematically impossible"}, {"weight": "HIGH", "pain_point_name": "Pricing Confusion / Unit Economics Breakdown", "indian_specific_nuance": "Indian market pressure to underprice is severe; founders regularly set prices 60-70% below what Western comparable customers would pay", "why_high_risk_in_this_vertical": "SaaS pricing is complex — seat-based, usage-based, outcome-based all have different LTV implications"}, {"weight": "HIGH", "pain_point_name": "Wrong GTM for Target Market", "indian_specific_nuance": "Many Indian SaaS founders try to sell to Indian enterprises — long cycles, low budgets — while the real opportunity is US SMB — faster cycles, higher willingness to pay", "why_high_risk_in_this_vertical": "India-first versus global-first SaaS require entirely different GTM motions; conflating the two destroys both"}, {"weight": "MEDIUM-HIGH", "pain_point_name": "Feature Bloat / No Product Discipline", "indian_specific_nuance": "Indian engineering culture glorifies feature volume; product discipline and saying no to customer requests is culturally uncomfortable", "why_high_risk_in_this_vertical": "Technical founders default to building; in SaaS this creates product complexity that kills adoption and increases churn"}, {"weight": "MEDIUM", "pain_point_name": "Fundraising at Wrong Stage", "indian_specific_nuance": "Indian SaaS angels and seed funds have grown but Series A is still primarily available only to capital-efficient businesses with INR 3-5 Crore ARR", "why_high_risk_in_this_vertical": "SaaS VCs expect ARR milestones before leading rounds; founders often raise too early or too late"}, {"weight": "MEDIUM", "pain_point_name": "Founder as Bottleneck / No Sales System", "indian_specific_nuance": "Indian technical founders have strong product conviction but deep sales aversion; the cultural discomfort with asking for money is amplified", "why_high_risk_in_this_vertical": "Technical founders avoid sales; in SaaS the founder must be the first salesperson and build a repeatable motion before hiring"}, {"weight": "MEDIUM", "pain_point_name": "Ignoring Retention / Focusing Only on Acquisition", "indian_specific_nuance": "Indian SaaS companies rarely track NRR; the concept of expansion revenue within existing accounts is underdeveloped", "why_high_risk_in_this_vertical": "NRR is the single most important SaaS metric — companies with NRR above 120% grow without new customers"}]', '{"report_framing": "All benchmarks use SaaS-specific comparators.", "question_bank_filtering": "Industry-specific sub-questions are surfaced. A SaaS founder gets questions about NRR and cohort retention.", "intervention_library_filtering": "Only SaaS-relevant frameworks are surfaced.", "root_cause_probability_weighting": "Churn and pricing confusion get higher initial probability weights."}', 'Churn above 3% monthly. LTV:CAC below 3:1. Payback period above 18 months. No expansion revenue. Pricing below Rs 999 per month for B2B SaaS.', '{"stage_3_exit": "MRR Rs 50,000", "stage_4_exit": "MRR Rs 5,00,000", "stage_5_entry": "ARR Rs 50,00,000 and above"}') on conflict do nothing;
insert into "industries" ("industry_id", "industry_code", "industry_name", "description", "defining_characteristics", "top_pain_point_weights", "key_metrics", "red_flags", "empathy_language", "recommended_benchmarks", "created_at", "updated_at", "industry_subtitle", "why_industry_context_matters", "top_pain_points", "diagnostic_adjustments", "red_flags_description", "stage_thresholds_inr") values ('2', 'services', 'Services & Consulting', 'Management consulting, IT services, design agencies, coaching, legal, accounting, staffing, and freelance platforms. Revenue is people-delivered, not product-delivered. Scaling means hiring, not deployment, unless the founder deliberately productises services into scalable offerings.', '["India is the world''s largest services economy — services startups are structurally different because revenue is people-delivered, not product-delivered; scaling means hiring, not deployment", "The single biggest trap: revenue is linear — more clients means more people needed — unless the founder deliberately productises services into scalable offerings", "Client concentration risk is extreme — most Indian services startups have 1 to 3 clients contributing more than 60% of revenue; losing one client can be existential", "Family businesses and referral networks are the dominant GTM in Indian services — digital marketing and cold outreach work differently; trust and relationship capital matter more than in other verticals"]', '{"TM-004": 1.05, "GTM-003": 1.15, "GTM-005": 1.3, "OPS-001": 1.15, "OPS-002": 1.3, "OPS-004": 1.05, "PRD-005": 1.5, "SAL-004": 1.5}', '["Revenue per employee", "Client concentration (% from top 3 clients)", "Gross margin per project", "Utilisation rate", "Average project duration", "Retainer vs project revenue ratio", "NPS (Net Promoter Score)", "Referral rate"]', '{"retainer_revenue": "zero retainer revenue is a red flag", "gross_margin_pct_below": 35, "written_contracts_with_scope": "absence is a red flag", "single_client_revenue_pct_above": 40, "founder_billable_hours_pct_above": 60}', '{"use": ["clients", "engagements", "billable hours", "proposals", "retainers", "service-market fit"], "avoid": [{"say": "clients", "instead_of": "users"}, {"say": "service-market fit", "instead_of": "product-market fit"}], "psychological_framing": "Services founders carry the weight of being personally responsible for every client relationship."}', '{"gross_margin_min_pct": 40, "revenue_per_employee_INR_min": 1500000, "retainer_revenue_min_pct_of_total": 30, "client_concentration_max_pct_per_client": 30}', '2026-07-10 11:24:52.14702+00', '2026-07-11 04:28:09.765561+00', 'Management consulting, IT services, design agencies, coaching, legal, accounting, staffing, freelance platforms', 'A weak sales pipeline for a services founder is a distribution channel and relationship problem — not a CRM or outbound problem.', '[{"weight": "CRITICAL", "pain_point_name": "Client Concentration / Dependency", "indian_specific_nuance": "Indian consulting founders often resist diversification because large clients are prestigious", "why_high_risk_in_this_vertical": "One client representing 50%+ of revenue creates existential fragility"}, {"weight": "CRITICAL", "pain_point_name": "No Productised Service / Linear Scaling Trap", "indian_specific_nuance": "Indian service founders pride themselves on customisation which is actually a scalability blocker", "why_high_risk_in_this_vertical": "Services revenue scales with headcount; without productisation the founder can never exit the delivery loop"}, {"weight": "HIGH", "pain_point_name": "Pricing Below Market Value", "indian_specific_nuance": "Indian founders face intense client pressure to discount; many price 40-60% below market value", "why_high_risk_in_this_vertical": "Services founders chronically underprice because pricing feels personal"}, {"weight": "HIGH", "pain_point_name": "Founder Doing All Delivery", "indian_specific_nuance": "Indian clients often hire the founder personally not the firm", "why_high_risk_in_this_vertical": "In services the founder is often the most valuable deliverer; removing themselves is the hardest transition"}, {"weight": "MEDIUM-HIGH", "pain_point_name": "No Referral or Reputation System", "indian_specific_nuance": "Indian founders rely heavily on personal networks which are finite", "why_high_risk_in_this_vertical": "Services businesses grow through reputation and referrals"}, {"weight": "MEDIUM-HIGH", "pain_point_name": "Poor Scoping and Contract Discipline", "indian_specific_nuance": "Indian business culture makes saying no to client requests uncomfortable", "why_high_risk_in_this_vertical": "Scope creep destroys profitability in services"}, {"weight": "MEDIUM", "pain_point_name": "No Recurring Revenue / Project Dependency", "indian_specific_nuance": "Indian services founders rarely design retainer models proactively", "why_high_risk_in_this_vertical": "Project-based revenue creates constant business development pressure"}, {"weight": "MEDIUM", "pain_point_name": "Hiring and Team Quality", "indian_specific_nuance": "Indian services founders struggle to hire quality talent at early stages", "why_high_risk_in_this_vertical": "Services quality is determined by team quality"}]', '{"report_framing": "Benchmarks use services-specific comparators.", "question_bank_filtering": "A services founder gets questions about client concentration and delivery dependency.", "intervention_library_filtering": "Services founders need productisation, pricing, referral system, and delegation frameworks.", "root_cause_probability_weighting": "Client concentration and delivery bottleneck get higher initial probability weights."}', 'Single client above 40% of revenue. Gross margin below 35%. Founder delivering more than 60% of billable hours. No written contracts. Zero retainer revenue.', '{"stage_3_exit": "Monthly billing Rs 2,00,000", "stage_4_exit": "Monthly billing Rs 10,00,000", "stage_5_entry": "Annual billing Rs 1,00,00,000 and above with at least 5 clients"}') on conflict do nothing;
insert into "industries" ("industry_id", "industry_code", "industry_name", "description", "defining_characteristics", "top_pain_point_weights", "key_metrics", "red_flags", "empathy_language", "recommended_benchmarks", "created_at", "updated_at", "industry_subtitle", "why_industry_context_matters", "top_pain_points", "diagnostic_adjustments", "red_flags_description", "stage_thresholds_inr") values ('3', 'manufacturing', 'Manufacturing & D2C', 'Physical product brands, FMCG, fashion, food and beverage, electronics, home goods, and exporters. Revenue requires inventory investment before it arrives. Working capital management is the dominant operational challenge.', '["India''s manufacturing sector is experiencing its strongest decade — PLI schemes, China+1 strategy, and domestic consumption boom are creating structural tailwinds", "Working capital is the dominant challenge — physical products require inventory investment before revenue", "Supply chain concentration risk is extreme — many Indian manufacturers depend on a single supplier region for components", "D2C brands face a fundamental tension between high customer acquisition costs versus low repeat purchase rates"]', '{"GTM-003": 1.15, "GTM-007": 1.3, "OPS-001": 1.5, "OPS-004": 1.5, "OPS-006": 1.15, "PRD-004": 1.05, "SAL-003": 1.3, "SCL-039": 1.05}', '["Gross margin before channel fees", "Gross margin after channel fees", "Working capital cycle (days)", "Inventory turnover", "Customer repeat rate at 90 days", "CAC by channel", "Return rate", "Supply chain concentration"]', '{"compliance_documentation": "zero compliance documentation is a critical red flag", "gross_margin_d2c_pct_below": 40, "working_capital_cycle_days_above": 90, "repeat_purchase_rate_90day_pct_below": 20, "single_supplier_key_inputs_pct_above": 60}', '{"use": ["SKU", "GMV", "inventory", "supply chain", "channel margins", "customers", "demand validation"], "avoid": [{"say": "customers", "instead_of": "users"}, {"say": "demand validation", "instead_of": "product-market fit"}], "psychological_framing": "Manufacturing founders carry the fear of inventory obsolescence and cash running out before the next order arrives."}', '{"cac_ltv_ratio_min": 3, "gross_margin_min_pct": 55, "repeat_rate_90day_min_pct": 30, "marketplace_dependency_max_pct": 50, "working_capital_cycle_max_days": 60}', '2026-07-10 11:24:52.14702+00', '2026-07-11 04:28:09.765561+00', 'Physical product brands, FMCG, fashion, food and beverage, electronics, home goods, exporters', 'Supply chain disruptions and working capital cycles create failure modes that simply do not exist in software businesses.', '[{"weight": "CRITICAL", "pain_point_name": "Working Capital Mismanagement", "indian_specific_nuance": "Indian manufacturers often use personal savings rather than structured invoice financing", "why_high_risk_in_this_vertical": "Physical product businesses require 60-120 day cash cycles; poor working capital management collapses even profitable businesses"}, {"weight": "CRITICAL", "pain_point_name": "Supply Chain Concentration", "indian_specific_nuance": "Post-COVID Indian founders increased China dependency creating unpredictable cost structures", "why_high_risk_in_this_vertical": "Dependence on one supplier for key inputs creates existential fragility"}, {"weight": "HIGH", "pain_point_name": "No Repeat Purchase / High CAC", "indian_specific_nuance": "Indian D2C founders overinvest in acquisition and underinvest in retention", "why_high_risk_in_this_vertical": "D2C unit economics require repeat purchase to be viable"}, {"weight": "HIGH", "pain_point_name": "Pricing vs Cost Confusion", "indian_specific_nuance": "Indian retail channels compress margins significantly; founders often do not model channel economics", "why_high_risk_in_this_vertical": "Many founders price on cost-plus basis without understanding competitive positioning"}, {"weight": "MEDIUM-HIGH", "pain_point_name": "Distribution Channel Errors", "indian_specific_nuance": "India distribution complexity is unique across Tier 1 2 and 3 cities", "why_high_risk_in_this_vertical": "Wrong channel choice kills reach and unit economics simultaneously"}, {"weight": "MEDIUM-HIGH", "pain_point_name": "Regulatory and Compliance Gaps", "indian_specific_nuance": "Indian founders routinely underestimate compliance complexity", "why_high_risk_in_this_vertical": "Manufacturing requires FSSAI BIS ISO GST factory licences — non-compliance creates existential risk"}, {"weight": "MEDIUM", "pain_point_name": "Quality Consistency at Scale", "indian_specific_nuance": "Many Indian founders scale production before quality systems are established", "why_high_risk_in_this_vertical": "Manufacturing quality degrades as volumes increase without quality systems"}, {"weight": "MEDIUM", "pain_point_name": "Marketplace Dependency", "indian_specific_nuance": "Indian D2C brands with 80%+ revenue from Amazon are not building a brand", "why_high_risk_in_this_vertical": "Over-dependence on marketplaces removes direct customer relationships"}]', '{"report_framing": "A 35% gross margin is a red flag in SaaS but healthy in manufacturing.", "question_bank_filtering": "Manufacturing founders get questions about supplier concentration and inventory management.", "intervention_library_filtering": "Inventory management, channel strategy, and working capital frameworks are prioritised.", "root_cause_probability_weighting": "Cash flow mismanagement and supply chain dependencies are high-probability root causes."}', 'Working capital cycle above 90 days with no financing facility. Single supplier above 60% of key inputs. Repeat purchase rate below 20% at 90 days. Gross margin below 40% for D2C. Zero compliance documentation.', '{"stage_3_exit": "Monthly GMV Rs 5,00,000", "stage_4_exit": "Monthly GMV Rs 30,00,000", "stage_5_entry": "Annual GMV Rs 5 Crore and above with repeat rate above 30%"}') on conflict do nothing;
insert into "industries" ("industry_id", "industry_code", "industry_name", "description", "defining_characteristics", "top_pain_point_weights", "key_metrics", "red_flags", "empathy_language", "recommended_benchmarks", "created_at", "updated_at", "industry_subtitle", "why_industry_context_matters", "top_pain_points", "diagnostic_adjustments", "red_flags_description", "stage_thresholds_inr") values ('4', 'ngo', 'Social Impact & NGO', 'Non-profits, NGOs, impact-driven social enterprises, CSR-funded ventures, and hybrid organisations. Funding is primarily grant and donor-based. Founders must balance commercial viability with social mission while navigating FCRA compliance and impact measurement requirements.', '["India has over 3.3 million registered NGOs — more than any country in the world — but fewer than 10% are operationally active with stable funding", "The hybrid model tension is uniquely Indian: social enterprises must balance commercial viability with social mission", "FCRA compliance is a critical risk — many international funding flows are subject to FCRA restrictions that can be revoked", "Impact measurement is both a fundraising tool and a mission accountability mechanism"]', '{"TM-002": 1.15, "FND-001": 1.5, "GTM-004": 1.05, "OPS-002": 1.05, "OPS-005": 1.3, "OPS-006": 1.3, "PSY-007": 1.3, "SAL-004": 1.5}', '["Funding concentration (% from top 3 donors)", "Earned vs grant revenue ratio", "Programme expense ratio (target 70%+)", "Impact metrics per rupee spent", "Staff retention rate", "FCRA compliance status", "Months of operating reserve"]', '{"earned_revenue": "zero earned revenue is a critical red flag", "fcra_compliance": "non-compliance is a critical red flag", "theory_of_change_document": "absence is a red flag", "operating_reserve_months_below": 3, "single_donor_funding_pct_above": 50}', '{"use": ["beneficiaries", "donors", "grants", "programmes", "impact", "mission", "funding"], "avoid": [{"say": "beneficiaries", "instead_of": "customers"}, {"say": "funding or income", "instead_of": "revenue"}, {"say": "programme", "instead_of": "product"}], "psychological_framing": "NGO founders carry mission weight that commercial founders do not. Never frame financial sustainability as being in conflict with mission."}', '{"operating_reserve_months_min": 6, "staff_retention_annual_min_pct": 70, "earned_revenue_min_pct_of_total": 20, "programme_expense_ratio_min_pct": 70, "single_donor_concentration_max_pct": 30}', '2026-07-10 11:24:52.14702+00', '2026-07-11 04:28:09.765561+00', 'Non-profits, NGOs, impact-driven social enterprises, CSR-funded ventures, hybrid organisations', 'The entire language, metric set, and psychological context of this vertical is different from commercial businesses.', '[{"weight": "CRITICAL", "pain_point_name": "Donor Concentration / Funding Dependency", "indian_specific_nuance": "Indian NGOs are heavily dependent on CSR funding; changes in CSR priorities can collapse operations", "why_high_risk_in_this_vertical": "Dependence on one or two large donors creates existential fragility at renewal time"}, {"weight": "CRITICAL", "pain_point_name": "No Earned Revenue / 100% Grant Dependency", "indian_specific_nuance": "Indian social enterprises resist commercialisation as a perceived dilution of mission", "why_high_risk_in_this_vertical": "Organisations with zero earned revenue are structurally vulnerable to any grant delay"}, {"weight": "HIGH", "pain_point_name": "Weak Impact Measurement Systems", "indian_specific_nuance": "Indian NGOs use anecdotal impact reporting; the shift to quantified outcome metrics requires capabilities most founders do not have", "why_high_risk_in_this_vertical": "Donors require credible auditable impact data; organisations without measurement systems cannot access larger funding"}, {"weight": "HIGH", "pain_point_name": "Founder Burnout from Mission Weight", "indian_specific_nuance": "Indian social sector founders face cultural pressure that prevents them from seeking support", "why_high_risk_in_this_vertical": "Social sector founders carry extraordinary emotional weight involving human suffering"}, {"weight": "HIGH", "pain_point_name": "FCRA and Regulatory Compliance Risk", "indian_specific_nuance": "The Indian government has cancelled FCRA licences of thousands of NGOs", "why_high_risk_in_this_vertical": "FCRA cancellation blocks foreign funding entirely"}, {"weight": "MEDIUM-HIGH", "pain_point_name": "Team Recruitment and Retention", "indian_specific_nuance": "Indian social sector professionals face family pressure to join a proper company", "why_high_risk_in_this_vertical": "Social sector salaries cannot compete with corporate"}, {"weight": "MEDIUM", "pain_point_name": "No Succession or Institutional Independence", "indian_specific_nuance": "Indian NGO founders resist building institutional systems because donor relationships are personal", "why_high_risk_in_this_vertical": "Many Indian NGOs are founder-dependent; the founder IS the organisation"}, {"weight": "MEDIUM", "pain_point_name": "Communication and Storytelling Gap", "indian_specific_nuance": "Indian NGO founders are often skilled practitioners but poor communicators", "why_high_risk_in_this_vertical": "Donors fund stories as much as data; organisations that cannot communicate impact lose funding"}]', '{"report_framing": "Programme expense ratio, donor concentration, and operating reserve are the primary health metrics.", "question_bank_filtering": "NGO founders get questions about donor concentration and impact measurement.", "intervention_library_filtering": "NGO founders never see SaaS metrics frameworks.", "root_cause_probability_weighting": "Donor concentration and grant dependency get highest initial probability weights."}', 'Single donor above 50% of funding. Zero earned revenue. No Theory of Change document. FCRA non-compliance. Months of reserve below 3.', '{"stage_3_exit": "Annual budget Rs 30,00,000 with at least 2 donors", "stage_4_entry": "Annual budget Rs 1 Crore and above with 5 or more donors", "stage_5_entry": "Annual budget Rs 5 Crore and above with 20% or more earned revenue"}') on conflict do nothing;
